import{_ as o,o as s,c as t,a2 as a}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-036 — Venus: the three sites use the Moon and Mars gallery ladder, so each has a hero and a GALLERY tab","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-036-venus-galleries-use-the-worlds-ladder.md","filePath":"uxs/decisions/UXD-036-venus-galleries-use-the-worlds-ladder.md"}'),r={name:"uxs/decisions/UXD-036-venus-galleries-use-the-worlds-ladder.md"};function d(n,e,i,l,c,h){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="uxd-036-—-venus-the-three-sites-use-the-moon-and-mars-gallery-ladder-so-each-has-a-hero-and-a-gallery-tab" tabindex="-1">UXD-036 — Venus: the three sites use the Moon and Mars gallery ladder, so each has a hero and a GALLERY tab <a class="header-anchor" href="#uxd-036-—-venus-the-three-sites-use-the-moon-and-mars-gallery-ladder-so-each-has-a-hero-and-a-gallery-tab" aria-label="Permalink to &quot;UXD-036 — Venus: the three sites use the Moon and Mars gallery ladder, so each has a hero and a GALLERY tab&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by unit tests, e2e on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed 2026-11-13, decided and built)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-13-slice-D3-brief.md</code> §12 approved as written (&quot;Ok with all 12&quot;: D-decisions 8a and 9a); &quot;don&#39;t touch heroes ... what we have now is good&quot; (2026-11-14)</li><li><strong>Answers</strong>: VE1 of the UX feedback plan; slice D3</li><li><strong>Builds on</strong>: <a href="./UXD-025-lists-carry-a-round-photo">UXD-025</a> (the INDEX photo is the image the panel shows), <a href="./UXD-034-worlds-orbiter-detail-tab-and-panorama-opening">UXD-034</a> (the photo comes first; its guard test judged nothing on Venus until now)</li><li><strong>Changes</strong>: <code>src/lib/data/galleries.ts</code> (<code>getSurfaceSiteGallery</code>; the three site loaders are one-line calls), <code>src/lib/data/galleries.test.ts</code> and <code>galleries-frozen.json</code> (new), <code>src/lib/data.test.ts</code>, <code>tests/e2e/venus-sites.spec.ts</code> (new), <code>tests/e2e/surface-panel-order.spec.ts</code>, <code>tests/e2e/a11y.spec.ts</code>. No file under <code>static/images/</code> or <code>static/data/</code> changed.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><strong>VE1.</strong> &quot;No gallery on any of the 3 sites, including no hero images.&quot; <code>getVenusSiteGallery()</code> was <code>return []</code>, so a Venus panel had no hero and no GALLERY tab, while the INDEX row of the same site already showed a photograph (UXD-025, 3 of 3).</p><p>The images exist: the mission galleries hold 3 (<code>venera-13</code>), 4 (<code>vega-1</code>) and 3 (<code>vega-2</code>) images, the fleet galleries 4 each, with provenance rows; the hero slots are already blessed in <code>missions-hero-overrides.json</code> (venera-13 <code>02</code>, vega-1 <code>02</code>, vega-2 <code>03</code>).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>One ladder for the three Worlds (decision 8a).</strong> <code>getSurfaceSiteGallery(body, siteId, missionId)</code> holds the steps once: the body&#39;s own manifest, the mission gallery by <code>mission_id</code> then by site id, the fleet gallery by every id variant of <code>mission_id</code> then of the site id, then the body&#39;s hero override. <code>getMoonSiteGallery</code>, <code>getMarsSiteGallery</code> and <code>getVenusSiteGallery</code> are one-line calls. Venus has no own manifest and no <code>venus-sites-hero-overrides.json</code>: the body&#39;s table entry for it names neither, so the own rung and the override fetch are skipped (a missing override file would be a 404 on every Venus panel); the mission and fleet rungs apply their own overrides, as for every body. <code>HeroSurface</code> is unchanged. A fourth world is one table row.</li><li><strong>The blessed heroes stay (decision 9a).</strong> Venera 13 <code>missions/venera-13/02</code> (the lander&#39;s own frame of the surface), Vega 1 <code>missions/vega-1/02</code> (probe hardware), Vega 2 <code>missions/vega-2/03</code> (the craft in a museum hall). The INDEX thumbs already showed them; the panel now shows the same image. No hero image, slot, override or gallery order is changed (operator, 2026-11-14).</li><li><strong>Moon and Mars come out as they were.</strong> <code>galleries-frozen.json</code> holds what the two separate loaders returned for every site (28 Moon, 27 Mars, hero override applied), frozen before the refactor; <code>galleries.test.ts</code> compares the shared ladder to it.</li><li><strong>The photo-first guard now judges Venus.</strong> <code>surface-panel-order.spec.ts</code> no longer exempts <code>/venus</code> from its minimum count (3 sites with a gallery; Moon and Mars keep 20); <code>venus-sites.spec.ts</code> checks, for each Venus site, the hero (by slot) before the tab row, the GALLERY tab with 2, 3 and 2 thumbs, the credit line and the lightbox from the hero.</li><li><strong>Hero = INDEX thumb, for all three bodies.</strong> <code>galleries.test.ts</code> asserts that the first gallery image of every Moon, Mars and Venus site has the same folder and slot as <code>thumbOfSite</code> (UXD-025).</li><li><strong>The entity page <code>/venus/&lt;id&gt;</code> has no photo hero to agree</strong> (NV2): <code>SiteEntityPage</code> (shared by <code>/moon</code>, <code>/mars</code>, <code>/venus</code>) draws the site&#39;s illustration and facts only; no Venus site has an illustration, so nothing on the page disagrees with the panel hero. Not changed.</li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: <code>galleries.test.ts</code> (55 Moon and Mars sites equal to the frozen file, the three Venus sites, hero = thumb on all 58 sites), <code>data.test.ts</code>. E2E on desktop, mobile and mobile-landscape against the dev server: <code>venus-sites.spec.ts</code>, <code>surface-panel-order.spec.ts</code>, the Venus rows of <code>a11y.spec.ts</code> (0 violations). Screenshots read, desktop and phone: the three Venus panels before (empty galleries, the old panel) and after, the GALLERY tab, Luna 17 and Spirit beside them.</p><p>Not checked: a real device, Firefox and WebKit; the Venus Share card and the <code>ru</code> and <code>ar</code> panels were not shot.</p>',10)])])}const p=o(r,[["render",d]]);export{g as __pageData,p as default};
